import type { ReadableStream } from 'node:stream/web'

/**
 * A running Studio HTTP server.
 */
export type StudioServer = {
  /**
   * Shuts down the server and stops accepting new connections.
   */
  close(): void
}

export type StartStudioServerOptions = {
  /**
   * Handles an incoming request and produces the response to send back.
   */
  handler: (request: Request) => Response | Promise<Response>

  /**
   * Invoked once the server is ready to accept connections.
   */
  onListen: () => void

  /**
   * The port to listen on.
   */
  port: number
}

/**
 * Starts an HTTP server that delegates incoming requests to the provided `handler`.
 *
 * `HEAD` requests are answered with the same status as the equivalent `GET` request but with an empty body.
 * When the handler throws, the server responds with a plain-text `500` and logs the error.
 */
export function startStudioServer({ handler, onListen, port }: StartStudioServerOptions): StudioServer {
  const server = createServer((req, res) => {
    void handleRequest(handler, req, res)
  })

  server.listen(port, onListen)

  return {
    close() {
      server.close()
    },
  }
}

async function handleRequest(
  handler: StartStudioServerOptions['handler'],
  req: IncomingMessage,
  res: ServerResponse,
): Promise<void> {
  const isHead = req.method === 'HEAD'

  let response: Response

  try {
    response = await handler(toWebRequest(req, isHead ? 'GET' : (req.method ?? 'GET')))
  } catch (error) {
    console.error('[Prisma Studio]', error)

    res.statusCode = 500
    res.setHeader('access-control-allow-origin', '*')
    res.setHeader('content-type', 'text/plain; charset=utf-8')
    res.end(error instanceof Error ? error.message : String(error))
    return
  }

  res.statusCode = response.status

  response.headers.forEach((value, name) => {
    res.setHeader(name, value)
  })

  if (isHead || response.body === null) {
    res.end()
    return
  }

  Readable.fromWeb(response.body as ReadableStream<Uint8Array>).pipe(res)
}

function toWebRequest(req: IncomingMessage, method: string): Request {
  const host = req.headers.host ?? 'localhost'
  const url = `http://${host}${req.url ?? '/'}`

  const headers = new Headers()

  for (const [name, value] of Object.entries(req.headers)) {
    if (value === undefined) {
      continue
    }

    if (Array.isArray(value)) {
      for (const item of value) {
        headers.append(name, item)
      }
    } else {
      headers.set(name, value)
    }
  }

